    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        String password = br.readLine().trim();

        List<List<Character>> options = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            String word = br.readLine().trim();
            TreeSet<Character> set = new TreeSet<>();
            for (int j = 0; j < word.length(); j++) {
                set.add(word.charAt(j));
            }
            options.add(new ArrayList<>(set));
        }

        long P = Long.parseLong(br.readLine().trim());
        long CAP = 1_000_000_001L;

        long[] suffix = new long[M + 1];
        suffix[M] = 1;

        for (int i = M - 1; i >= 0; i--) {
            long cnt = options.get(i).size();
            if (suffix[i + 1] > CAP / cnt) {
                suffix[i] = CAP;
            } else {
                suffix[i] = suffix[i + 1] * cnt;
            }
        }

        StringBuilder sb = new StringBuilder();
        int blurIndex = 0;

        for (int i = 0; i < N; i++) {
            char ch = password.charAt(i);
            if (ch == '#') {
                List<Character> opts = options.get(blurIndex);
                for (char c : opts) {
                    long blockSize = suffix[blurIndex + 1];
                    if (P > blockSize) {
                        P -= blockSize;
                    } else {
                        sb.append(c);
                        break;
                    }
                }
                blurIndex++;
            } else {
                sb.append(ch);
            }
        }

        System.out.println(sb.toString());
    }
